type Matrix<T> = Vec<Vec<T>>;

fn broadcast(a: Vec<i8>, shape: Vec<u8>) -> Matrix<i8> {
    debug_assert!(shape.len() == 2, "shape must have length 2");
    debug_assert!(!a.is_empty(), "input array must have positive length");

    let r = shape[0] as usize;
    let c = shape[1] as usize;

    debug_assert!(r > 0 && c > 0, "R and C must be positive");
    debug_assert!(
        a.len() == r || a.len() == c,
        "array length must match either R or C"
    );

    let mut ret: Matrix<i8> = Vec::with_capacity(r);

    if a.len() == r {
        // Column vector broadcast across columns: ret[i][j] = a[i]
        for i in 0..r {
            let val = a[i];
            let mut row = Vec::with_capacity(c);
            row.resize(c, val);
            ret.push(row);
        }
    } else {
        // Row vector broadcast across rows: ret[i][j] = a[j]
        // a.len() == c guaranteed by debug_assert above (or by problem assumptions).
        for _ in 0..r {
            ret.push(a.clone());
        }
    }

    ret
}